begin;select plan(12);select has_table('public','apostolic_unit_catalog');select has_table('public','apostolic_city_garrison');select has_table('public','apostolic_training_queue');select is((select count(*)::integer from public.apostolic_unit_catalog),4,'four starter units');select is((select count(*)::integer from public.apostolic_unit_catalog where costs?'gems'),0,'no gems');select function_returns('public','apostolic_get_defense_center',array[]::text[],'jsonb');select function_returns('public','apostolic_start_unit_training',array['text','integer','uuid'],'jsonb');select function_returns('public','apostolic_finish_unit_training',array[]::text[],'jsonb');select has_index('public','apostolic_training_queue','apostolic_training_one_active_idx');select col_is_pk('public','apostolic_city_garrison',array['city_id','unit_code']);select ok((select bool_and(defense>0)from public.apostolic_unit_catalog),'positive defense');select ok((select bool_and(space>0)from public.apostolic_unit_catalog),'positive space');select*from finish();rollback;
